changeSet.sql:
SET LOCAL lock_timeout = '5s';

-- ---- the manifest
CREATE OR REPLACE FUNCTION nexus.catalog_document_chunks_name_from_chunk()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_chunk_id  bigint;
    v_stored    text;
    v_key       text;
    v_state     text;
BEGIN
    IF NEW.collection_id IS NULL THEN
        RETURN NEW;
    END IF;
    -- An UPDATE that does not move the key (a stamp of collection_id, a position change) needs no lookup.
    IF TG_OP = 'UPDATE'
       AND NEW.collection IS NOT DISTINCT FROM OLD.collection
       AND NEW.tenant_id = OLD.tenant_id
       AND NEW.chash = OLD.chash
       AND NEW.embedding_model IS NOT DISTINCT FROM OLD.embedding_model THEN
        RETURN NEW;
    END IF;
    -- 1. The chunk under the name the writer supplied (the primary key).
    SELECT c.collection_id INTO v_chunk_id
      FROM nexus.chunks c
     WHERE c.tenant_id = NEW.tenant_id AND c.collection = NEW.collection
       AND c.chash = NEW.chash AND c.embedding_model = NEW.embedding_model;
    IF FOUND AND (v_chunk_id IS NULL OR v_chunk_id = NEW.collection_id) THEN
        RETURN NEW;
    END IF;
    -- 2. The chunk of the child's collection, whatever name it is stored under.
    SELECT c.collection INTO v_stored
      FROM nexus.chunks c
     WHERE c.tenant_id = NEW.tenant_id AND c.collection_id = NEW.collection_id
       AND c.chash = NEW.chash AND c.embedding_model = NEW.embedding_model
     LIMIT 1;
    IF NOT FOUND OR v_stored = NEW.collection THEN
        RETURN NEW;
    END IF;
    v_key := 'nexus.child_name_fix_' || TG_TABLE_NAME;
    v_state := pg_catalog.current_setting(v_key, true);
    IF v_state IS NULL OR v_state = '' THEN
        PERFORM pg_catalog.set_config(v_key, '1|' || NEW.collection || ' -> ' || v_stored, true);
    ELSE
        PERFORM pg_catalog.set_config(v_key,
            (pg_catalog.split_part(v_state, '|', 1)::integer + 1)::text || '|'
                || pg_catalog.substr(v_state, pg_catalog.strpos(v_state, '|') + 1), true);
    END IF;
    NEW.collection := v_stored;
    RETURN NEW;
END;
$function$;

