-- ---- topic_assignments (the name is source_collection, the chunk's chash is doc_id)
CREATE OR REPLACE FUNCTION nexus.topic_assignments_name_from_chunk()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_chunk_id  bigint;
    v_stored    text;
    v_key       text;
    v_state     text;
BEGIN
    IF NEW.source_collection_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE'
       AND NEW.source_collection IS NOT DISTINCT FROM OLD.source_collection
       AND NEW.tenant_id = OLD.tenant_id
       AND NEW.doc_id = OLD.doc_id
       AND NEW.embedding_model IS NOT DISTINCT FROM OLD.embedding_model THEN
        RETURN NEW;
    END IF;
    SELECT c.collection_id INTO v_chunk_id
      FROM nexus.chunks c
     WHERE c.tenant_id = NEW.tenant_id AND c.collection = NEW.source_collection
       AND c.chash = NEW.doc_id AND c.embedding_model = NEW.embedding_model;
    IF FOUND AND (v_chunk_id IS NULL OR v_chunk_id = NEW.source_collection_id) THEN
        RETURN NEW;
    END IF;
    SELECT c.collection INTO v_stored
      FROM nexus.chunks c
     WHERE c.tenant_id = NEW.tenant_id AND c.collection_id = NEW.source_collection_id
       AND c.chash = NEW.doc_id AND c.embedding_model = NEW.embedding_model
     LIMIT 1;
    IF NOT FOUND OR v_stored = NEW.source_collection THEN
        RETURN NEW;
    END IF;
    v_key := 'nexus.child_name_fix_' || TG_TABLE_NAME;
    v_state := pg_catalog.current_setting(v_key, true);
    IF v_state IS NULL OR v_state = '' THEN
        PERFORM pg_catalog.set_config(v_key, '1|' || NEW.source_collection || ' -> ' || v_stored, true);
    ELSE
        PERFORM pg_catalog.set_config(v_key,
            (pg_catalog.split_part(v_state, '|', 1)::integer + 1)::text || '|'
                || pg_catalog.substr(v_state, pg_catalog.strpos(v_state, '|') + 1), true);
    END IF;
    NEW.source_collection := v_stored;
    RETURN NEW;
END;
$function$;

-- ---- the once-per-statement line, shared by the three tables
CREATE OR REPLACE FUNCTION nexus.child_name_fix_log()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_key    text := 'nexus.child_name_fix_' || TG_TABLE_NAME;
    v_state  text := pg_catalog.current_setting(v_key, true);
BEGIN
    IF v_state IS NOT NULL AND v_state <> '' THEN
        PERFORM pg_catalog.set_config(v_key, '', true);
        RAISE LOG 'RDR-229: nexus.% took the chunk''s stored collection name on % row(s) of one statement (first: %)',
            TG_TABLE_NAME, pg_catalog.split_part(v_state, '|', 1),
            pg_catalog.substr(v_state, pg_catalog.strpos(v_state, '|') + 1);
    END IF;
    RETURN NULL;
END;
$function$;

REVOKE EXECUTE ON FUNCTION nexus.catalog_document_chunks_name_from_chunk() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION nexus.chunk_orphaned_at_name_from_chunk() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION nexus.topic_assignments_name_from_chunk() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION nexus.child_name_fix_log() FROM PUBLIC;

CREATE TRIGGER trg_catalog_document_chunks_name_from_chunk
    BEFORE INSERT OR UPDATE ON nexus.catalog_document_chunks
    FOR EACH ROW
    EXECUTE FUNCTION nexus.catalog_document_chunks_name_from_chunk();
CREATE TRIGGER trg_catalog_document_chunks_name_fix_log
    AFTER INSERT OR UPDATE ON nexus.catalog_document_chunks
    FOR EACH STATEMENT
    EXECUTE FUNCTION nexus.child_name_fix_log();

CREATE TRIGGER trg_chunk_orphaned_at_name_from_chunk
    BEFORE INSERT OR UPDATE ON nexus.chunk_orphaned_at
    FOR EACH ROW
    EXECUTE FUNCTION nexus.chunk_orphaned_at_name_from_chunk();
CREATE TRIGGER trg_chunk_orphaned_at_name_fix_log
    AFTER INSERT OR UPDATE ON nexus.chunk_orphaned_at
    FOR EACH STATEMENT
    EXECUTE FUNCTION nexus.child_name_fix_log();

CREATE TRIGGER trg_topic_assignments_name_from_chunk
    BEFORE INSERT OR UPDATE ON nexus.topic_assignments
    FOR EACH ROW
    EXECUTE FUNCTION nexus.topic_assignments_name_from_chunk();
CREATE TRIGGER trg_topic_assignments_name_fix_log
    AFTER INSERT OR UPDATE ON nexus.topic_assignments
    FOR EACH STATEMENT
    EXECUTE FUNCTION nexus.child_name_fix_log();

rollback.sql:
DROP TRIGGER IF EXISTS trg_topic_assignments_name_fix_log ON nexus.topic_assignments;
DROP TRIGGER IF EXISTS trg_topic_assignments_name_from_chunk ON nexus.topic_assignments;
DROP TRIGGER IF EXISTS trg_chunk_orphaned_at_name_fix_log ON nexus.chunk_orphaned_at;
DROP TRIGGER IF EXISTS trg_chunk_orphaned_at_name_from_chunk ON nexus.chunk_orphaned_at;
DROP TRIGGER IF EXISTS trg_catalog_document_chunks_name_fix_log ON nexus.catalog_document_chunks;
DROP TRIGGER IF EXISTS trg_catalog_document_chunks_name_from_chunk ON nexus.catalog_document_chunks;
DROP FUNCTION IF EXISTS nexus.child_name_fix_log();
DROP FUNCTION IF EXISTS nexus.topic_assignments_name_from_chunk();
DROP FUNCTION IF EXISTS nexus.chunk_orphaned_at_name_from_chunk();
DROP FUNCTION IF EXISTS nexus.catalog_document_chunks_name_from_chunk();
